from pathlib import Path
import ast
import inspect
import re
import pandas as pd


# ==========================================================================================
# 1. Search priority sources around Notebook 48
# ==========================================================================================

SEARCH_ROOTS_2B = [
    PROJECT_ROOT / "scripts",
    PROJECT_ROOT / "src",
    PROJECT_ROOT / "reports" / "notebook48",
    PROJECT_ROOT / "artifacts" / "notebook48",
    PROJECT_ROOT / "outputs" / "notebook48",
]

BASELINE_NAMES_2B = [
    "Depth-6 Search Baseline",
    "Greedy Damage Baseline",
    "Random Baseline",
]

SEARCH_TERMS_2B = [
    "Depth-6 Search Baseline",
    "Greedy Damage Baseline",
    "Random Baseline",
    "competitive_policy_baseline_tournament",
    "baseline_tournament",
    "greedy",
    "random",
    "depth",
]


candidate_files_2b = []


for root in SEARCH_ROOTS_2B:

    if not root.exists():
        continue

    for path in root.rglob("*"):

        if not path.is_file():
            continue

        if "__pycache__" in path.parts:
            continue

        if path.suffix.lower() not in {
            ".py",
            ".json",
            ".txt",
            ".md",
            ".csv",
        }:
            continue

        try:

            text = path.read_text(
                encoding="utf-8-sig",
                errors="ignore",
            )

        except Exception:
            continue

        text_lower = text.lower()

        matched_terms = [
            term
            for term in SEARCH_TERMS_2B
            if term.lower() in text_lower
        ]

        if not matched_terms:
            continue

        candidate_files_2b.append(
            {
                "file":
                    str(
                        path.relative_to(
                            PROJECT_ROOT
                        )
                    ),

                "matched_terms":
                    matched_terms,

                "size_bytes":
                    path.stat().st_size,
            }
        )


section2b_candidate_files_df = pd.DataFrame(
    candidate_files_2b
)


print("\nNOTEBOOK 48 BASELINE / HARNESS CANDIDATE FILES")
print("-" * 100)

display(
    section2b_candidate_files_df
    .drop_duplicates(
        subset=["file"]
    )
    .reset_index(drop=True)
)


# ==========================================================================================
# 2. Search Python sources for class/function definitions
# ==========================================================================================

definition_rows_2b = []


for root in [
    PROJECT_ROOT / "scripts",
    PROJECT_ROOT / "src",
]:

    if not root.exists():
        continue

    for path in root.rglob("*.py"):

        if "__pycache__" in path.parts:
            continue

        try:

            source_text = path.read_text(
                encoding="utf-8-sig",
                errors="ignore",
            )

            tree = ast.parse(
                source_text
            )

        except Exception:
            continue


        # ------------------------------------------------------------------
        # Keep only files containing Notebook 48 benchmark terminology
        # ------------------------------------------------------------------

        lower_text = source_text.lower()

        if not any(
            term.lower() in lower_text
            for term in SEARCH_TERMS_2B
        ):
            continue


        for node in ast.walk(tree):

            if isinstance(
                node,
                ast.ClassDef,
            ):

                source_segment = ast.get_source_segment(
                    source_text,
                    node,
                )

                source_segment_lower = (
                    source_segment.lower()
                    if source_segment
                    else ""
                )

                if any(
                    token in (
                        node.name.lower()
                        + " "
                        + source_segment_lower
                    )
                    for token in [
                        "baseline",
                        "greedy",
                        "random",
                        "search",
                        "agent",
                    ]
                ):

                    definition_rows_2b.append(
                        {
                            "file":
                                str(
                                    path.relative_to(
                                        PROJECT_ROOT
                                    )
                                ),

                            "object_type":
                                "CLASS",

                            "name":
                                node.name,

                            "line_number":
                                node.lineno,

                            "source":
                                source_segment,
                        }
                    )


            elif isinstance(
                node,
                (
                    ast.FunctionDef,
                    ast.AsyncFunctionDef,
                ),
            ):

                source_segment = ast.get_source_segment(
                    source_text,
                    node,
                )

                source_segment_lower = (
                    source_segment.lower()
                    if source_segment
                    else ""
                )

                if any(
                    token in (
                        node.name.lower()
                        + " "
                        + source_segment_lower
                    )
                    for token in [
                        "baseline",
                        "greedy",
                        "random",
                        "search",
                        "tournament",
                        "match",
                        "battle",
                    ]
                ):

                    definition_rows_2b.append(
                        {
                            "file":
                                str(
                                    path.relative_to(
                                        PROJECT_ROOT
                                    )
                                ),

                            "object_type":
                                "FUNCTION",

                            "name":
                                node.name,

                            "line_number":
                                node.lineno,

                            "source":
                                source_segment,
                        }
                    )


section2b_definitions_df = pd.DataFrame(
    definition_rows_2b
)


