for object_name in CRITICAL_OBJECTS_2D:

    object_source = (
        objects_2d[
            object_name
        ][
            "source"
        ]
    )

    object_tree = ast.parse(
        object_source
    )

    referenced_names = {
        node.id
        for node in ast.walk(
            object_tree
        )
        if isinstance(
            node,
            ast.Name,
        )
    }

    local_names = set()

    for node in ast.walk(
        object_tree
    ):

        if isinstance(
            node,
            ast.arg,
        ):
            local_names.add(
                node.arg
            )

        elif isinstance(
            node,
            (
                ast.FunctionDef,
                ast.ClassDef,
            ),
        ):
            local_names.add(
                node.name
            )

    probable_globals = sorted(
        referenced_names
        -
        local_names
        -
        {
            "self",
            "True",
            "False",
            "None",
        }
    )

    dependency_rows_2d.append(
        {
            "object":
                object_name,

            "probable_global_dependencies":
                probable_globals,
        }
    )


