# ==========================================================================================

R3_ASSIGNMENT_TOKENS_3A = [
    "r3_live_model",
    "r3_live_feature_names",
    "R3",
    "NOTEBOOK53",
    "MODEL_PATH",
    "FEATURE",
    "joblib",
]


assignment_rows_3a = []


for node in tree_3a.body:

    if not isinstance(
        node,
        (
            ast.Assign,
            ast.AnnAssign,
        ),
    ):
        continue

    source_segment = ast.get_source_segment(
        source_3a,
        node,
    )

    if not source_segment:
        continue

    source_lower = source_segment.lower()

    if not any(
        token.lower()
        in source_lower
        for token in R3_ASSIGNMENT_TOKENS_3A
    ):
        continue


    assigned_names = []


    if isinstance(
        node,
        ast.Assign,
    ):

        targets = node.targets

    else:

        targets = [
            node.target
        ]


    for target in targets:

        if isinstance(
            target,
            ast.Name,
        ):

            assigned_names.append(
                target.id
            )

        elif isinstance(
            target,
            (
                ast.Tuple,
                ast.List,
            ),
        ):

            for element in target.elts:

                if isinstance(
                    element,
                    ast.Name,
                ):

                    assigned_names.append(
                        element.id
                    )


    assignment_rows_3a.append(
        {
            "line_number":
                getattr(
                    node,
                    "lineno",
                    None,
                ),

            "assigned_names":
                assigned_names,

            "source":
                source_segment,
        }
    )


