for encoded_name in (
    R3_CATEGORICAL_FEATURES_ENCODED_3B3
):

    suffix = encoded_name.replace(
        "categorical__",
        "",
        1,
    )

    matched_source = None
    matched_value = None


    # Longest names first avoids prefix ambiguity.
    for raw_column in sorted(
        raw_categorical_columns_3b3,
        key=len,
        reverse=True,
    ):

        prefix = (
            raw_column
            + "_"
        )

        if suffix.startswith(
            prefix
        ):

            matched_source = (
                raw_column
            )

            matched_value = (
                suffix[
                    len(
                        prefix
                    ):
                ]
            )

            break


    categorical_mapping_rows_3b3.append(
        {
            "encoded_feature":
                encoded_name,

            "raw_source_column":
                matched_source,

            "category_value":
                matched_value,

            "source_present":
                (
                    matched_source
                    in raw_feature_row_3a5.columns
                    if matched_source
                    is not None
                    else False
                ),
        }
    )


