import ast
import builtins
import pandas as pd

required_3b4b = [
    "encode_r3_feature_row",
    "tree_3a",
    "source_3a",
]

missing_3b4b = [
    name for name in required_3b4b
    if name not in globals()
]

if missing_3b4b:
    print("Section 3B.4B deferred. Missing:", missing_3b4b)
    print("Run Sections 3A through 3B.4A in order, then rerun this cell.")
else:
    def _true_external_names_3b4b(function_node):
        local_names = set()

        for arg in function_node.args.args:
            local_names.add(arg.arg)
        for arg in function_node.args.kwonlyargs:
            local_names.add(arg.arg)
        if function_node.args.vararg is not None:
            local_names.add(function_node.args.vararg.arg)
        if function_node.args.kwarg is not None:
            local_names.add(function_node.args.kwarg.arg)

        for node in ast.walk(function_node):
            if isinstance(node, ast.Name) and isinstance(node.ctx, (ast.Store, ast.Param)):
                local_names.add(node.id)

        loaded_names = {
            node.id
            for node in ast.walk(function_node)
            if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Load)
        }

        return sorted(
            loaded_names
            - local_names
            - set(dir(builtins))
        )

    encoder_node_3b4b = next(
        (
            node for node in tree_3a.body
            if isinstance(node, ast.FunctionDef)
            and node.name == "encode_r3_feature_row"
        ),
        None,
    )

    assert encoder_node_3b4b is not None, "Exact Notebook 59 encoder definition was not found."

    true_encoder_globals_3b4b = _true_external_names_3b4b(
        encoder_node_3b4b
    )

    rows_3b4b = []
    for name in true_encoder_globals_3b4b:
        rows_3b4b.append(
            {
                "name": name,
                "available": name in globals(),
                "object_type": (
                    type(globals()[name]).__name__
                    if name in globals()
                    else "MISSING"
                ),
            }
        )

    section3b4b_dependency_df = pd.DataFrame(rows_3b4b)

    print("\\nTRUE ENCODER GLOBAL REFERENCES")
    print("-" * 100)
    display(section3b4b_dependency_df)

    unresolved_3b4b = [
        row["name"]
        for row in rows_3b4b
        if not row["available"]
    ]

