import ast
import pandas as pd
import numpy as np


TARGET_3B4C = (
    "R3_CATEGORICAL_SOURCE_COLUMNS"
)


# ==========================================================================================
# 1. Locate EVERY top-level assignment to the target in Notebook 59
# ==========================================================================================

assignment_chain_3b4c = []


for node in tree_3a.body:

    if not isinstance(
        node,
        (
            ast.Assign,
            ast.AnnAssign,
        ),
    ):
        continue


    targets = (
        node.targets
        if isinstance(
            node,
            ast.Assign,
        )
        else [
            node.target
        ]
    )


    assigned_names = []

    for target in targets:

        if isinstance(
            target,
            ast.Name,
        ):

            assigned_names.append(
                target.id
            )


    if TARGET_3B4C not in assigned_names:
        continue


    source_segment = (
        ast.get_source_segment(
            source_3a,
            node,
        )
    )


    # ------------------------------------------------------------------
    # Detect whether the assignment reads itself on the RHS
    # ------------------------------------------------------------------

    loaded_names = {
        child.id
        for child in ast.walk(
            node
        )
        if (
            isinstance(
                child,
                ast.Name,
            )
            and
            isinstance(
                child.ctx,
                ast.Load,
            )
        )
    }


    assignment_chain_3b4c.append(
        {
            "line_number":
                node.lineno,

            "end_line":
                getattr(
                    node,
                    "end_lineno",
                    None,
                ),

            "self_referential":
                TARGET_3B4C
                in loaded_names,

            "node":
                node,

            "source":
                source_segment,
        }
    )


assignment_chain_3b4c = sorted(
    assignment_chain_3b4c,
    key=lambda row:
        row[
            "line_number"
        ],
)


