# 6. Locate Notebook 59 sources for missing dependencies
# ==========================================================================================

dependency_source_rows_3c1 = []


for dependency_name in (
    missing_dependencies_3c1
):

    matches = []


    for node in tree_3a.body:

        # ------------------------------------------------------------------
        # Definition
        # ------------------------------------------------------------------

        if (
            isinstance(
                node,
                (
                    ast.FunctionDef,
                    ast.ClassDef,
                ),
            )
            and
            node.name
            ==
            dependency_name
        ):

            matches.append(
                {
                    "dependency":
                        dependency_name,

                    "source_type":
                        type(
                            node
                        ).__name__,

                    "line_number":
                        node.lineno,

                    "end_line":
                        node.end_lineno,

                    "source":
                        ast.get_source_segment(
                            source_3a,
                            node,
                        ),
                }
            )


        # ------------------------------------------------------------------
        # Assignment
        # ------------------------------------------------------------------

        elif isinstance(
            node,
            (
                ast.Assign,
                ast.AnnAssign,
            ),
        ):

            targets = (
                node.targets
                if isinstance(
                    node,
                    ast.Assign,
                )
                else [
                    node.target
                ]
            )


            assigned_names = [
                target.id
                for target in targets
                if isinstance(
                    target,
                    ast.Name,
                )
            ]


            if (
                dependency_name
                in assigned_names
            ):

                matches.append(
                    {
                        "dependency":
                            dependency_name,

                        "source_type":
                            type(
                                node
                            ).__name__,

                        "line_number":
                            node.lineno,

                        "end_line":
                            node.end_lineno,

                        "source":
                            ast.get_source_segment(
                                source_3a,
                                node,
                            ),
                    }
                )


    if matches:

        dependency_source_rows_3c1.extend(
            matches
        )

    else:

        dependency_source_rows_3c1.append(
            {
                "dependency":
                    dependency_name,

                "source_type":
                    "NOT_FOUND",

                "line_number":
                    None,

                "end_line":
                    None,

                "source":
                    None,
            }
        )


