# ======================================================================================
# Helper: recover exact function/class source by AST
# ======================================================================================

def source_for_symbol_4d5a(
    path: Path,
    symbol_name: str,
):
    text = path.read_text(
        encoding="utf-8-sig",
        errors="replace",
    )

    tree = ast.parse(text)

    lines = text.splitlines()

    matches = []

    for node in ast.walk(tree):

        if isinstance(
            node,
            (
                ast.FunctionDef,
                ast.AsyncFunctionDef,
                ast.ClassDef,
            ),
        ):

            if node.name == symbol_name:

                start = node.lineno

                end = getattr(
                    node,
                    "end_lineno",
                    node.lineno,
                )

                matches.append(
                    (
                        start,
                        end,
                        "\n".join(
                            lines[
                                start - 1:
                                end
                            ]
                        ),
                    )
                )

    return matches


def print_symbol_4d5a(
    path: Path,
    symbol_name: str,
    max_lines: int = 260,
):
    matches = source_for_symbol_4d5a(
        path,
        symbol_name,
    )

    print()
    print("=" * 100)
    print(
        f"{path.name} :: {symbol_name}"
    )
    print("=" * 100)

    if not matches:
        print("NOT FOUND")
        return []

    for match_number, (
        start,
        end,
        source,
    ) in enumerate(
        matches,
        start=1,
    ):

        source_lines = source.splitlines()

        print(
            f"Occurrence {match_number}"
        )
        print(
            f"Lines {start} - {end}"
        )
        print("-" * 100)

        for offset, line in enumerate(
            source_lines[:max_lines],
            start=start,
        ):
            print(
                f"{offset:5d}: {line}"
            )

        if len(source_lines) > max_lines:
            print(
                f"... truncated after "
                f"{max_lines} lines ..."
            )

    return matches


