    def true_global_references_4d5b(
        fn,
    ):

        try:

            source = textwrap.dedent(
                inspect.getsource(fn)
            )

            tree = ast.parse(
                source
            )

        except Exception:

            return []

        local_names = set()

        loaded_names = set()

        for node in ast.walk(tree):

            if isinstance(
                node,
                ast.arg,
            ):

                local_names.add(
                    node.arg
                )

            elif isinstance(
                node,
                ast.Name,
            ):

                if isinstance(
                    node.ctx,
                    ast.Store,
                ):

                    local_names.add(
                        node.id
                    )

                elif isinstance(
                    node.ctx,
                    ast.Load,
                ):

                    loaded_names.add(
                        node.id
                    )

        builtin_names = set(
            dir(__builtins__)
        )

        globals_used = sorted(
            name
            for name in loaded_names
            if (
                name not in local_names
                and
                name not in builtin_names
            )
        )

        return globals_used


