def _card_name_4d5j(
    card_4d5j,
):

    if isinstance(
        card_4d5j,
        dict,
    ):

        return str(
            card_4d5j.get(
                "name",
                card_4d5j.get(
                    "card_name",
                    "",
                ),
            )
        )


    return str(
        getattr(
            card_4d5j,
            "name",
            getattr(
                card_4d5j,
                "card_name",
                "",
            ),
        )
    )


template_map_4d5j = {
    _card_name_4d5j(
        card_4d5j
    ):
        card_4d5j
    for card_4d5j
    in TOURNAMENT_CARD_TEMPLATES
}


print("\nTOURNAMENT CARD MAP")
print("-" * 100)

print(
    sorted(
        template_map_4d5j.keys()
    )
)


