# 4. NOTEBOOK 59 AST — FIND ACTION / CLASS / LABEL ASSIGNMENTS
#
# Search list/tuple/set literals containing frozen action-class strings.
# ==========================================================================================

action_literal_rows_4d5k = []


def _assignment_target_names_4d5k(
    node_4d5k,
):

    names_4d5k = []


    targets_4d5k = []


    if isinstance(
        node_4d5k,
        ast.Assign,
    ):

        targets_4d5k = (
            node_4d5k.targets
        )


    elif isinstance(
        node_4d5k,
        ast.AnnAssign,
    ):

        targets_4d5k = [
            node_4d5k.target
        ]


    for target_4d5k in targets_4d5k:

        if isinstance(
            target_4d5k,
            ast.Name,
        ):

            names_4d5k.append(
                target_4d5k.id
            )


        elif isinstance(
            target_4d5k,
            ast.Attribute,
        ):

            names_4d5k.append(
                target_4d5k.attr
            )


    return names_4d5k


for node_4d5k in ast.walk(
    tree_3a
):

    if not isinstance(
        node_4d5k,
        (
            ast.Assign,
            ast.AnnAssign,
        ),
    ):

        continue


    source_segment_4d5k = (
        ast.get_source_segment(
            source_3a,
            node_4d5k,
        )
    )


    if not source_segment_4d5k:

        continue


    matched_actions_4d5k = [
        action_name_4d5k
        for action_name_4d5k
        in frozen_action_classes_4d5k
        if action_name_4d5k.lower()
        in source_segment_4d5k.lower()
    ]


    if not matched_actions_4d5k:

        continue


    target_names_4d5k = (
        _assignment_target_names_4d5k(
            node_4d5k
        )
    )


    action_literal_rows_4d5k.append(
        {
            "line_number":
                getattr(
                    node_4d5k,
                    "lineno",
                    None,
                ),

            "targets":
                target_names_4d5k,

            "matched_actions":
                matched_actions_4d5k,

            "source":
                source_segment_4d5k[:2000],
        }
    )


