def parse_possible_list_4d5q(value):

    if isinstance(
        value,
        (list, tuple, set),
    ):
        return list(value)

    if pd.isna(value):
        return None

    text_4d5q = str(value).strip()

    if not text_4d5q:
        return None

    try:

        parsed_4d5q = ast.literal_eval(
            text_4d5q
        )

        if isinstance(
            parsed_4d5q,
            (list, tuple, set),
        ):
            return list(
                parsed_4d5q
            )

    except Exception:
        pass

    try:

        parsed_4d5q = json.loads(
            text_4d5q
        )

        if isinstance(
            parsed_4d5q,
            list,
        ):
            return parsed_4d5q

    except Exception:
        pass

    return None


