def read_text_safely_4d5s(
    path_4d5s,
):

    raw_bytes_4d5s = (
        Path(
            path_4d5s
        ).read_bytes()
    )

    # Strip UTF-8 BOM if present.
    if raw_bytes_4d5s.startswith(
        b"\xef\xbb\xbf"
    ):

        raw_bytes_4d5s = (
            raw_bytes_4d5s[3:]
        )

    for encoding_4d5s in [
        "utf-8",
        "utf-8-sig",
        "cp1252",
        "latin-1",
    ]:

        try:

            return raw_bytes_4d5s.decode(
                encoding_4d5s
            )

        except UnicodeDecodeError:

            continue

    return raw_bytes_4d5s.decode(
        "utf-8",
        errors="replace",
    )


