# ==========================================================================================
# 13. SAFE TABULAR LOADER
# ==========================================================================================

def load_table_safely_4d5s(
    path_4d5s,
):

    suffix_4d5s = (
        path_4d5s.suffix.lower()
    )

    try:

        if suffix_4d5s == ".csv":

            return pd.read_csv(
                path_4d5s,
                low_memory=False,
            )

        if suffix_4d5s == ".parquet":

            return pd.read_parquet(
                path_4d5s
            )

        if suffix_4d5s in {
            ".pkl",
            ".pickle",
        }:

            loaded_4d5s = pd.read_pickle(
                path_4d5s
            )

            if isinstance(
                loaded_4d5s,
                pd.DataFrame,
            ):

                return loaded_4d5s

    except Exception:

        return None

    return None


