def load_parent_table_4d5t(
    path_4d5t,
):

    path_4d5t = Path(
        path_4d5t
    )

    suffix_4d5t = (
        path_4d5t.suffix.lower()
    )

    try:

        if suffix_4d5t == ".csv":

            table_4d5t = pd.read_csv(
                path_4d5t,
                low_memory=False,
            )

        elif suffix_4d5t == ".parquet":

            table_4d5t = pd.read_parquet(
                path_4d5t
            )

        elif suffix_4d5t in {
            ".pkl",
            ".pickle",
        }:

            table_4d5t = pd.read_pickle(
                path_4d5t
            )

        else:

            return (
                None,
                "UNSUPPORTED_SUFFIX",
            )


        if not isinstance(
            table_4d5t,
            pd.DataFrame,
        ):

            return (
                None,
                (
                    "Loaded object is "
                    f"{type(table_4d5t).__name__}, "
                    "not DataFrame."
                ),
            )


        return (
            table_4d5t,
            None,
        )


    except Exception as error_4d5t:

        return (
            None,
            (
                f"{type(error_4d5t).__name__}: "
                f"{error_4d5t}"
            ),
        )


