def parse_state_features_4d5v(value):
    """
    Convert state_features into a safely inspectable Python object.

    No semantic interpretation is performed here.
    """

    if value is None:

        return None, "none", False, None


    if isinstance(
        value,
        dict,
    ):

        return value, "dict", True, len(value)


    if isinstance(
        value,
        np.ndarray,
    ):

        parsed = value.tolist()

        return (
            parsed,
            "ndarray",
            True,
            len(parsed),
        )


    if isinstance(
        value,
        tuple,
    ):

        parsed = list(value)

        return (
            parsed,
            "tuple",
            True,
            len(parsed),
        )


    if isinstance(
        value,
        list,
    ):

        return (
            value,
            "list",
            True,
            len(value),
        )


    if isinstance(
        value,
        str,
    ):

        stripped = value.strip()

        if not stripped:

            return (
                None,
                "empty_string",
                False,
                None,
            )


        # --------------------------------------------------------------
        # Try JSON first
        # --------------------------------------------------------------

        try:

            parsed = json.loads(
                stripped
            )

            parsed_length = (
                len(parsed)
                if hasattr(
                    parsed,
                    "__len__",
                )
                else None
            )

            return (
                parsed,
                "json_string",
                True,
                parsed_length,
            )

        except Exception:

            pass


        # --------------------------------------------------------------
        # Then safe Python literal parsing
        # --------------------------------------------------------------

        try:

            parsed = ast.literal_eval(
                stripped
            )

            parsed_length = (
                len(parsed)
                if hasattr(
                    parsed,
                    "__len__",
                )
                else None
            )

            return (
                parsed,
                "literal_string",
                True,
                parsed_length,
            )

        except Exception:

            return (
                value,
                "unparsed_string",
                False,
                len(value),
            )


    return (
        value,
        type(value).__name__,
        False,
        None,
    )


