# ==========================================================================================
# 7. AST HELPER FUNCTIONS
# ==========================================================================================

def safe_unparse_4d5w(
    node_4d5w,
):

    try:

        return ast.unparse(
            node_4d5w
        )

    except Exception:

        return (
            f"<{type(node_4d5w).__name__}>"
        )


def target_names_4d5w(
    node_4d5w,
):

    names_4d5w = []


    if isinstance(
        node_4d5w,
        ast.Name,
    ):

        names_4d5w.append(
            node_4d5w.id
        )


    elif isinstance(
        node_4d5w,
        (
            ast.Tuple,
            ast.List,
        ),
    ):

        for element_4d5w in node_4d5w.elts:

            names_4d5w.extend(
                target_names_4d5w(
                    element_4d5w
                )
            )


    elif isinstance(
        node_4d5w,
        ast.Attribute,
    ):

        names_4d5w.append(
            safe_unparse_4d5w(
                node_4d5w
            )
        )


    elif isinstance(
        node_4d5w,
        ast.Subscript,
    ):

        names_4d5w.append(
            safe_unparse_4d5w(
                node_4d5w
            )
        )


    return names_4d5w


