state_assignment_rows_4d5w = []
candidate_vector_assignments_4d5w = []


for path_4d5w, source_bundle_4d5w in (
    source_cache_4d5w.items()
):

    source_text_4d5w = (
        source_bundle_4d5w[
            "text"
        ]
    )


    try:

        source_tree_4d5w = ast.parse(
            source_text_4d5w,
            filename=str(
                path_4d5w
            ),
        )

    except Exception:

        continue


    for node_4d5w in ast.walk(
        source_tree_4d5w
    ):

        # ------------------------------------------------------------------
        # Standard assignment
        # ------------------------------------------------------------------

        if isinstance(
            node_4d5w,
            ast.Assign,
        ):

            target_texts_4d5w = []


            for target_4d5w in node_4d5w.targets:

                target_texts_4d5w.extend(
                    target_names_4d5w(
                        target_4d5w
                    )
                )


            target_match_4d5w = any(
                "state_feature"
                in target_text_4d5w.lower()
                for target_text_4d5w
                in target_texts_4d5w
            )


            if target_match_4d5w:

                value_text_4d5w = (
                    safe_unparse_4d5w(
                        node_4d5w.value
                    )
                )


                value_type_4d5w = (
                    type(
                        node_4d5w.value
                    ).__name__
                )


                list_length_4d5w = (
                    len(
                        node_4d5w.value.elts
                    )
                    if isinstance(
                        node_4d5w.value,
                        (
                            ast.List,
                            ast.Tuple,
                        ),
                    )
                    else None
                )


                state_assignment_rows_4d5w.append(
                    {
                        "path":
                            str(
                                path_4d5w
                            ),

                        "line_number":
                            getattr(
                                node_4d5w,
                                "lineno",
                                None,
                            ),

                        "assignment_type":
                            "Assign",

                        "targets":
                            target_texts_4d5w,

                        "value_type":
                            value_type_4d5w,

                        "sequence_length":
                            list_length_4d5w,

                        "source":
                            value_text_4d5w,
                    }
                )


                if (
                    list_length_4d5w
                    ==
                    8
                ):

                    expressions_4d5w = [
                        safe_unparse_4d5w(
                            element_4d5w
                        )
                        for element_4d5w
                        in node_4d5w.value.elts
                    ]


                    candidate_vector_assignments_4d5w.append(
                        {
                            "path":
                                str(
                                    path_4d5w
                                ),

                            "line_number":
                                getattr(
                                    node_4d5w,
                                    "lineno",
                                    None,
                                ),

                            "target":
                                target_texts_4d5w,

                            "expressions":
                                expressions_4d5w,

                            "source_kind":
                                "direct_8_element_assignment",
                        }
                    )


        # ------------------------------------------------------------------
        # Annotated assignment
        # ------------------------------------------------------------------

        elif isinstance(
            node_4d5w,
            ast.AnnAssign,
        ):

            target_text_4d5w = (
                safe_unparse_4d5w(
                    node_4d5w.target
                )
            )


            if (
                "state_feature"
                in target_text_4d5w.lower()
                and
                node_4d5w.value
                is not None
            ):

                value_text_4d5w = (
                    safe_unparse_4d5w(
                        node_4d5w.value
                    )
                )


                list_length_4d5w = (
                    len(
                        node_4d5w.value.elts
                    )
                    if isinstance(
                        node_4d5w.value,
                        (
                            ast.List,
                            ast.Tuple,
                        ),
                    )
                    else None
                )


                state_assignment_rows_4d5w.append(
                    {
                        "path":
                            str(
                                path_4d5w
                            ),

                        "line_number":
                            getattr(
                                node_4d5w,
                                "lineno",
                                None,
                            ),

                        "assignment_type":
                            "AnnAssign",

                        "targets":
                            [
                                target_text_4d5w
                            ],

                        "value_type":
                            type(
                                node_4d5w.value
                            ).__name__,

                        "sequence_length":
                            list_length_4d5w,

                        "source":
                            value_text_4d5w,
                    }
                )


                if (
                    list_length_4d5w
                    ==
                    8
                ):

                    expressions_4d5w = [
                        safe_unparse_4d5w(
                            element_4d5w
                        )
                        for element_4d5w
                        in node_4d5w.value.elts
                    ]


                    candidate_vector_assignments_4d5w.append(
                        {
                            "path":
                                str(
                                    path_4d5w
                                ),

                            "line_number":
                                getattr(
                                    node_4d5w,
                                    "lineno",
                                    None,
                                ),

                            "target":
                                [
                                    target_text_4d5w
                                ],

                            "expressions":
                                expressions_4d5w,

                            "source_kind":
                                "direct_8_element_annotated_assignment",
                        }
                    )


