def integer_like_summary_4d5y(
    values_4d5y,
):

    values_4d5y = np.asarray(
        values_4d5y,
        dtype=float,
    )


    nearest_integer_4d5y = (
        np.rint(
            values_4d5y
        )
    )


    residual_4d5y = np.abs(
        values_4d5y
        -
        nearest_integer_4d5y
    )


    return {
        "rows":
            int(
                len(
                    values_4d5y
                )
            ),

        "integer_like_rows":
            int(
                np.sum(
                    residual_4d5y
                    <=
                    1e-8
                )
            ),

        "max_integer_residual":
            float(
                np.max(
                    residual_4d5y
                )
            ),

        "minimum":
            float(
                np.min(
                    values_4d5y
                )
            ),

        "maximum":
            float(
                np.max(
                    values_4d5y
                )
            ),

        "unique_values":
            sorted(
                np.unique(
                    np.rint(
                        values_4d5y
                    )
                )
                .astype(int)
                .tolist()
            ),
    }


