def hand_hit_priority_4d5z(
    source_line_4d5z,
):
    """
    Higher score means stronger evidence that the line
    accesses or derives a pre-decision hand-size value.
    """

    text_4d5z = (
        source_line_4d5z
        .lower()
    )

    score_4d5z = 0

    if "hand_size" in text_4d5z:
        score_4d5z += 5

    if "len(" in text_4d5z and "hand" in text_4d5z:
        score_4d5z += 5

    if ".hand" in text_4d5z:
        score_4d5z += 4

    if "extract_hand_size" in text_4d5z:
        score_4d5z += 6

    if "opening_hand_size" in text_4d5z:
        score_4d5z += 3

    if "battle_state" in text_4d5z:
        score_4d5z += 2

    if "player" in text_4d5z:
        score_4d5z += 1

    if "opponent" in text_4d5z:
        score_4d5z += 1

    return score_4d5z


