# ==========================================================================================
# 6. SAFE ARTIFACT LOADER
# ==========================================================================================

def safe_load_candidate_4d5z3(
    path_value_4d5z3,
):

    path_4d5z3 = Path(
        path_value_4d5z3
    )

    suffix_4d5z3 = (
        path_4d5z3
        .suffix
        .lower()
    )

    try:

        if suffix_4d5z3 == ".csv":

            return (
                pd.read_csv(
                    path_4d5z3
                ),
                "pandas.read_csv",
                None,
            )

        if suffix_4d5z3 in {
            ".json",
            ".jsonl",
        }:

            try:

                return (
                    pd.read_json(
                        path_4d5z3,
                        lines=(
                            suffix_4d5z3
                            == ".jsonl"
                        ),
                    ),
                    "pandas.read_json",
                    None,
                )

            except Exception:

                with open(
                    path_4d5z3,
                    "r",
                    encoding="utf-8-sig",
                ) as handle_4d5z3:

                    payload_4d5z3 = json.load(
                        handle_4d5z3
                    )

                if isinstance(
                    payload_4d5z3,
                    list,
                ):

                    return (
                        pd.DataFrame(
                            payload_4d5z3
                        ),
                        "json.load",
                        None,
                    )

                if isinstance(
                    payload_4d5z3,
                    dict,
                ):

                    return (
                        pd.json_normalize(
                            payload_4d5z3
                        ),
                        "json_normalize",
                        None,
                    )

        if suffix_4d5z3 in {
            ".pkl",
            ".pickle",
        }:

            loaded_4d5z3 = pd.read_pickle(
                path_4d5z3
            )

            if isinstance(
                loaded_4d5z3,
                pd.DataFrame,
            ):

                return (
                    loaded_4d5z3,
                    "pandas.read_pickle",
                    None,
                )

            return (
                None,
                "pandas.read_pickle",
                (
                    "Loaded object was "
                    f"{type(loaded_4d5z3).__name__}, "
                    "not DataFrame."
                ),
            )

        if suffix_4d5z3 == ".parquet":

            try:

                loaded_4d5z3 = (
                    pd.read_parquet(
                        path_4d5z3
                    )
                )

                return (
                    loaded_4d5z3,
                    "pandas.read_parquet",
                    None,
                )

            except Exception as error_4d5z3:

                # Do not mutate the Arrow registry here.
                # A parquet failure is recorded as evidence.
                return (
                    None,
                    "pandas.read_parquet",
                    (
                        f"{type(error_4d5z3).__name__}: "
                        f"{error_4d5z3}"
                    ),
                )

        return (
            None,
            "unsupported",
            (
                "Unsupported persisted "
                f"suffix: {suffix_4d5z3}"
            ),
        )

    except Exception as error_4d5z3:

        return (
            None,
            "load_failed",
            (
                f"{type(error_4d5z3).__name__}: "
                f"{error_4d5z3}"
            ),
        )


