writer_context_rows_4d5z5 = []


def find_enclosing_python_scope_4d5z5(
    source_text_4d5z5,
    target_line_4d5z5,
):

    try:

        parsed_tree_4d5z5 = ast.parse(
            source_text_4d5z5
        )

    except Exception:

        return None, None


    best_node_4d5z5 = None


    for node_4d5z5 in ast.walk(
        parsed_tree_4d5z5
    ):

        if not isinstance(
            node_4d5z5,
            (
                ast.FunctionDef,
                ast.AsyncFunctionDef,
                ast.ClassDef,
            ),
        ):
            continue


        start_line_4d5z5 = getattr(
            node_4d5z5,
            "lineno",
            None,
        )

        end_line_4d5z5 = getattr(
            node_4d5z5,
            "end_lineno",
            None,
        )


        if (
            start_line_4d5z5 is None
            or
            end_line_4d5z5 is None
        ):
            continue


        if (
            start_line_4d5z5
            <=
            target_line_4d5z5
            <=
            end_line_4d5z5
        ):

            if (
                best_node_4d5z5 is None
                or
                (
                    end_line_4d5z5
                    -
                    start_line_4d5z5
                )
                <
                (
                    best_node_4d5z5.end_lineno
                    -
                    best_node_4d5z5.lineno
                )
            ):

                best_node_4d5z5 = (
                    node_4d5z5
                )


    if best_node_4d5z5 is None:

        return None, None


    return (
        type(
            best_node_4d5z5
        ).__name__,
        getattr(
            best_node_4d5z5,
            "name",
            None,
        ),
    )


