# 7. SAFE CANDIDATE LOADERS
# ==========================================================================================

def load_candidate_table_4d5z11(
    path_value_4d5z11,
):

    path_4d5z11 = Path(
        path_value_4d5z11
    )

    suffix_4d5z11 = (
        path_4d5z11
        .suffix
        .lower()
    )

    try:

        if suffix_4d5z11 == ".csv":

            return (
                pd.read_csv(
                    path_4d5z11
                ),
                "csv",
                None,
            )

        if suffix_4d5z11 == ".json":

            try:

                return (
                    pd.read_json(
                        path_4d5z11
                    ),
                    "json",
                    None,
                )

            except Exception:

                payload_4d5z11 = json.loads(
                    path_4d5z11.read_text(
                        encoding="utf-8-sig",
                        errors="replace",
                    )
                )

                if isinstance(
                    payload_4d5z11,
                    list,
                ):

                    return (
                        pd.DataFrame(
                            payload_4d5z11
                        ),
                        "json_records",
                        None,
                    )

                return (
                    None,
                    None,
                    "JSON payload is not a record list.",
                )

        if suffix_4d5z11 in {
            ".pkl",
            ".pickle",
        }:

            try:

                candidate_object_4d5z11 = (
                    pd.read_pickle(
                        path_4d5z11
                    )
                )

                if isinstance(
                    candidate_object_4d5z11,
                    pd.DataFrame,
                ):

                    return (
                        candidate_object_4d5z11,
                        "pickle",
                        None,
                    )

                return (
                    None,
                    None,
                    "Pickle object is not a DataFrame.",
                )

            except Exception as exc_4d5z11:

                return (
                    None,
                    None,
                    f"{type(exc_4d5z11).__name__}: {exc_4d5z11}",
                )

        if suffix_4d5z11 == ".parquet":

            try:

                return (
                    pd.read_parquet(
                        path_4d5z11
                    ),
                    "parquet",
                    None,
                )

            except Exception as exc_4d5z11:

                return (
                    None,
                    None,
                    f"{type(exc_4d5z11).__name__}: {exc_4d5z11}",
                )

        return (
            None,
            None,
            "Unsupported file type.",
        )

    except Exception as exc_4d5z11:

        return (
            None,
            None,
            f"{type(exc_4d5z11).__name__}: {exc_4d5z11}",
        )


