evaluation_name_patterns_4d6a = [
    r"evaluat",
    r"benchmark",
    r"tournament",
    r"match",
    r"battle",
    r"simulate",
    r"runner",
    r"play_game",
    r"run_game",
    r"run_match",
    r"run_battle",
]


agent_name_patterns_4d6a = [
    r"agent",
    r"policy",
    r"model",
    r"challenger",
    r"baseline",
    r"player",
]


result_name_patterns_4d6a = [
    r"result",
    r"summary",
    r"metrics",
    r"wins",
    r"losses",
    r"win_rate",
    r"benchmark",
    r"tournament",
]


# ==========================================================================================
# 3. DISCOVER CALLABLES
# ==========================================================================================

callable_rows_4d6a = []


for name_4d6a, value_4d6a in list(
    globals().items()
):

    if name_4d6a.startswith("_"):
        continue

    if not callable(
        value_4d6a
    ):
        continue


    name_lower_4d6a = (
        name_4d6a.lower()
    )


    matched_patterns_4d6a = [
        pattern_4d6a
        for pattern_4d6a
        in evaluation_name_patterns_4d6a
        if re.search(
            pattern_4d6a,
            name_lower_4d6a,
            flags=re.IGNORECASE,
        )
    ]


    if not matched_patterns_4d6a:
        continue


    try:

        signature_4d6a = str(
            inspect.signature(
                value_4d6a
            )
        )

    except Exception:

        signature_4d6a = None


    try:

        module_4d6a = (
            getattr(
                value_4d6a,
                "__module__",
                None,
            )
        )

    except Exception:

        module_4d6a = None


    callable_rows_4d6a.append(
        {
            "name":
                name_4d6a,

            "type":
                type(
                    value_4d6a
                ).__name__,

            "signature":
                signature_4d6a,

            "module":
                module_4d6a,

            "matched_patterns":
                matched_patterns_4d6a,
        }
    )


