# ==========================================================================================
# 3. SAFE BASELINE DESCRIPTION HELPER
# ==========================================================================================

def describe_baseline_4d6f(
    baseline_4d6f,
    collection_name_4d6f,
    index_4d6f,
):

    object_type_4d6f = type(
        baseline_4d6f
    ).__name__


    possible_name_attributes_4d6f = [
        "name",
        "agent_name",
        "baseline_name",
        "policy_name",
        "label",
    ]


    resolved_name_4d6f = None
    resolved_name_source_4d6f = None


    # ----------------------------------------------------------------------
    # Dict-like baseline
    # ----------------------------------------------------------------------

    if isinstance(
        baseline_4d6f,
        dict,
    ):

        for key_4d6f in (
            possible_name_attributes_4d6f
        ):

            if (
                key_4d6f
                in baseline_4d6f
                and
                baseline_4d6f[
                    key_4d6f
                ]
                is not None
            ):

                resolved_name_4d6f = str(
                    baseline_4d6f[
                        key_4d6f
                    ]
                )

                resolved_name_source_4d6f = (
                    f"dict[{key_4d6f!r}]"
                )

                break


    # ----------------------------------------------------------------------
    # Object-like baseline
    # ----------------------------------------------------------------------

    if resolved_name_4d6f is None:

        for attr_4d6f in (
            possible_name_attributes_4d6f
        ):

            try:

                attr_value_4d6f = getattr(
                    baseline_4d6f,
                    attr_4d6f,
                    None,
                )

            except Exception:

                attr_value_4d6f = None


            if attr_value_4d6f is not None:

                resolved_name_4d6f = str(
                    attr_value_4d6f
                )

                resolved_name_source_4d6f = (
                    f"attribute.{attr_4d6f}"
                )

                break


    # ----------------------------------------------------------------------
    # String baseline
    # ----------------------------------------------------------------------

    if (
        resolved_name_4d6f is None
        and
        isinstance(
            baseline_4d6f,
            str,
        )
    ):

        resolved_name_4d6f = (
            baseline_4d6f
        )

        resolved_name_source_4d6f = (
            "string_value"
        )


    # ----------------------------------------------------------------------
    # Agent-like methods
    # ----------------------------------------------------------------------

    agent_methods_4d6f = []


    for method_name_4d6f in [
        "select_action",
        "choose_action",
        "get_action",
        "act",
        "predict",
        "reset",
    ]:

        try:

            if callable(
                getattr(
                    baseline_4d6f,
                    method_name_4d6f,
                    None,
                )
            ):

                agent_methods_4d6f.append(
                    method_name_4d6f
                )

        except Exception:

            pass


    # ----------------------------------------------------------------------
    # Preview
    # ----------------------------------------------------------------------

    try:

        preview_4d6f = repr(
            baseline_4d6f
        )

    except Exception:

        preview_4d6f = (
            "<repr unavailable>"
        )


    if len(
        preview_4d6f
    ) > 800:

        preview_4d6f = (
            preview_4d6f[
                :800
            ]
            +
            "..."
        )


    return {
        "collection":
            collection_name_4d6f,

        "index":
            index_4d6f,

        "resolved_name":
            resolved_name_4d6f,

        "name_source":
            resolved_name_source_4d6f,

        "object_type":
            object_type_4d6f,

        "python_object_id":
            id(
                baseline_4d6f
            ),

        "agent_methods":
            agent_methods_4d6f,

        "agent_like":
            bool(
                agent_methods_4d6f
            ),

        "preview":
            preview_4d6f,
    }


