def semantic_score_4d6m(
    name_4d6m,
):

    name_lower_4d6m = str(
        name_4d6m
    ).lower()

    return sum(
        int(
            token_4d6m
            in
            name_lower_4d6m
        )
        for token_4d6m
        in semantic_tokens_4d6m
    )


