# ==========================================================================================
# 5. NORMALIZATION FUNCTION
# ==========================================================================================

def normalize_action_text_4d6n(
    value_4d6n,
):

    value_4d6n = str(
        value_4d6n
    ).strip().lower()

    value_4d6n = re.sub(
        r"[^a-z0-9]+",
        " ",
        value_4d6n,
    )

    value_4d6n = re.sub(
        r"\s+",
        " ",
        value_4d6n,
    ).strip()

    return value_4d6n


