# ==========================================================================================
# 3. NORMALIZATION HELPER
# ==========================================================================================

def normalize_class_4d6p(value_4d6p):

    value_4d6p = str(
        value_4d6p
    ).strip().lower()

    value_4d6p = re.sub(
        r"[^a-z0-9]+",
        " ",
        value_4d6p,
    )

    return re.sub(
        r"\s+",
        " ",
        value_4d6p,
    ).strip()


normalized_target_set_4d6p = {
    normalize_class_4d6p(x)
    for x in TOURNAMENT_TARGET_CLASSES_4D6P
}


# ==========================================================================================
# 4. AUDIT EVERY LIVE PREDICTIVE MODEL OBJECT
# ==========================================================================================

model_rows_4d6p = []


for name_4d6p, obj_4d6p in list(
    globals().items()
):

    if name_4d6p.startswith("_"):
        continue

    if not hasattr(
        obj_4d6p,
        "predict",
    ):
        continue


    classes_4d6p = None

    if hasattr(
        obj_4d6p,
        "classes_",
    ):

        try:

            classes_4d6p = [
                str(x)
                for x in list(
                    obj_4d6p.classes_
                )
            ]

        except Exception:

            classes_4d6p = None


    if not classes_4d6p:
        continue


    normalized_model_set_4d6p = {
        normalize_class_4d6p(x)
        for x in classes_4d6p
    }


    overlap_4d6p = sorted(
        normalized_model_set_4d6p
        &
        normalized_target_set_4d6p
    )


    missing_4d6p = sorted(
        normalized_target_set_4d6p
        -
        normalized_model_set_4d6p
    )


    extra_4d6p = sorted(
        normalized_model_set_4d6p
        -
        normalized_target_set_4d6p
    )


    exact_domain_match_4d6p = bool(
        normalized_model_set_4d6p
        ==
        normalized_target_set_4d6p
    )


    coverage_4d6p = (
        len(overlap_4d6p)
        /
        len(normalized_target_set_4d6p)
        if normalized_target_set_4d6p
        else 0.0
    )


    model_rows_4d6p.append(
        {
            "name":
                name_4d6p,

            "object_type":
                type(
                    obj_4d6p
                ).__name__,

            "python_object_id":
                id(
                    obj_4d6p
                ),

            "class_count":
                len(
                    classes_4d6p
                ),

            "classes":
                classes_4d6p,

            "overlap_count":
                len(
                    overlap_4d6p
                ),

            "target_coverage":
                coverage_4d6p,

            "missing_target_classes":
                missing_4d6p,

            "extra_model_classes":
                extra_4d6p,

            "exact_tournament_domain":
                exact_domain_match_4d6p,
        }
    )


