# ----------------------------------------------------------------------------------------------------
# 4. LEGAL-MOVE NAME HELPER
# ----------------------------------------------------------------------------------------------------

def normalize_runtime_move_name_4d6ah(
    move_value
):

    if move_value is None:
        return None

    if isinstance(
        move_value,
        str,
    ):
        return move_value.strip()

    if isinstance(
        move_value,
        dict,
    ):

        for key_4d6ah in [
            "name",
            "move_name",
            "action",
        ]:

            if (
                key_4d6ah
                in move_value
            ):

                return str(
                    move_value[
                        key_4d6ah
                    ]
                ).strip()

    for attr_4d6ah in [
        "name",
        "move_name",
        "action",
    ]:

        if hasattr(
            move_value,
            attr_4d6ah,
        ):

            value_4d6ah = getattr(
                move_value,
                attr_4d6ah,
            )

            if value_4d6ah is not None:

                return str(
                    value_4d6ah
                ).strip()

    return str(
        move_value
    ).strip()


# ----------------------------------------------------------------------------------------------------
# 5. CONTROLLED ADAPTER CLASS
# ----------------------------------------------------------------------------------------------------

class Controlled61FeatureTournamentAdapter4D6AH:

    def __init__(
        self,
        model,
        runtime_transform,
        feature_names,
        target_classes,
        decision_type,
        name="CONTROLLED_11_CLASS_61_FEATURE_AGENT",
    ):

        self.model = model

        self.runtime_transform = (
            runtime_transform
        )

        self.feature_names = list(
            feature_names
        )

        self.target_classes = list(
            target_classes
        )

        self.decision_type = (
            decision_type
        )

        self.name = name

        self.last_decision = None
        self.last_policy_result = None

        self.fit_calls = 0
        self.tournament_matches_executed = 0


    def choose_move(
        self,
        state=None,
        depth=None,
        battle_state=None,
        **kwargs,
    ):

        resolved_state = (
            state
            if state is not None
            else battle_state
        )

        if resolved_state is None:

            raise ValueError(
                "A battle state is required."
            )


        # --------------------------------------------------------------------------------------------
        # Recover exact simulator legal moves
        # --------------------------------------------------------------------------------------------

        legal_moves = list(
            get_current_legal_moves(
                resolved_state
            )
        )


        if len(
            legal_moves
        ) == 0:

            self.last_policy_result = {
                "selected_move": None,
                "selected_move_name": None,
                "fallback": True,
                "confidence": 0.0,
                "legal_probability_mass": 0.0,
            }

            self.last_decision = (
                self.decision_type(
                    move=None,
                    score=0.0,
                    search_depth=int(
                        depth or 0
                    ),
                    nodes=0,
                    confidence=0.0,
                    selected_move_name=None,
                    fallback=True,
                    reason="No legal moves available.",
                )
            )

            return self.last_decision


        # --------------------------------------------------------------------------------------------
        # Build exact frozen 61-feature row
        # --------------------------------------------------------------------------------------------

        feature_row = (
            self.runtime_transform(
                resolved_state
            )
        )


        if isinstance(
            feature_row,
            pd.Series,
        ):

            feature_row = (
                feature_row
                .to_frame()
                .T
            )


        elif isinstance(
            feature_row,
            np.ndarray,
        ):

            feature_row = pd.DataFrame(
                np.asarray(
                    feature_row
                ).reshape(
                    1,
                    -1
                ),
                columns=self.feature_names,
            )


        elif not isinstance(
            feature_row,
            pd.DataFrame,
        ):

            feature_row = pd.DataFrame(
                [
                    feature_row
                ]
            )


        # Exact column lock
        feature_row = (
            feature_row[
                self.feature_names
            ]
            .copy()
        )


        if feature_row.shape != (
            1,
            61,
        ):

            raise RuntimeError(
                "Runtime transform did not produce "
                "exactly one 61-feature row. "
                f"Observed: {feature_row.shape}"
            )


        feature_values = (
            feature_row
            .to_numpy(
                dtype=float
            )
        )


        if not np.isfinite(
            feature_values
        ).all():

            raise RuntimeError(
                "Runtime feature row contains "
                "non-finite values."
            )


        # --------------------------------------------------------------------------------------------
        # Certified model inference
        # --------------------------------------------------------------------------------------------

        probabilities = (
            self.model
            .predict_proba(
                feature_row
            )[0]
        )


        model_classes = list(
            self.model.classes_
        )


        if len(
            probabilities
        ) != 11:

            raise RuntimeError(
                "Certified model did not produce "
                "11-class probability vector."
            )


        probability_by_class = {
            str(
                class_name
            ):
            float(
                probability
            )

            for class_name, probability
            in zip(
                model_classes,
                probabilities,
            )
        }


        # --------------------------------------------------------------------------------------------
        # Map simulator legal moves to certified class vocabulary
        # --------------------------------------------------------------------------------------------

        legal_name_to_move = {}

        for legal_move in legal_moves:

            legal_name = (
                normalize_runtime_move_name_4d6ah(
                    legal_move
                )
            )

            if legal_name is not None:

                legal_name_to_move[
                    legal_name
                ] = legal_move


        certified_legal_names = [
            class_name
            for class_name
            in self.target_classes
            if class_name
            in legal_name_to_move
        ]


        # --------------------------------------------------------------------------------------------
        # Safety fallback
        # --------------------------------------------------------------------------------------------

        if len(
            certified_legal_names
        ) == 0:

            selected_move = (
                legal_moves[
                    0
                ]
            )

            selected_move_name = (
                normalize_runtime_move_name_4d6ah(
                    selected_move
                )
            )

            confidence = 0.0
            legal_probability_mass = 0.0
            fallback = True

            reason = (
                "No certified model class matched "
                "simulator legal moves."
            )


        else:

            legal_probability_mass = float(
                sum(
                    probability_by_class.get(
                        name,
                        0.0,
                    )
                    for name
                    in certified_legal_names
                )
            )


            selected_move_name = max(
                certified_legal_names,
                key=lambda name:
                    probability_by_class.get(
                        name,
                        0.0,
                    ),
            )


            selected_move = (
                legal_name_to_move[
                    selected_move_name
                ]
            )


            confidence = float(
                probability_by_class.get(
                    selected_move_name,
                    0.0,
                )
            )

            fallback = False

            reason = (
                "Certified 11-class model selected "
                "highest-probability simulator-legal move."
            )


        # --------------------------------------------------------------------------------------------
        # Final legality assertion
        # --------------------------------------------------------------------------------------------

        if selected_move not in legal_moves:

            raise AssertionError(
                "Controlled adapter selected a move "
                "outside simulator legal moves."
            )


        self.last_policy_result = {
            "selected_move":
                selected_move,

            "selected_move_name":
                selected_move_name,

            "confidence":
                confidence,

            "legal_probability_mass":
                legal_probability_mass,

            "fallback":
                fallback,

            "probability_by_class":
                probability_by_class,

            "legal_move_names":
                list(
                    legal_name_to_move.keys()
                ),
        }


        self.last_decision = (
            self.decision_type(
                move=selected_move,
                score=confidence,
                search_depth=int(
                    depth or 0
                ),
                nodes=0,
                confidence=confidence,
                selected_move_name=selected_move_name,
                fallback=fallback,
                reason=reason,
            )
        )


        return self.last_decision


# ----------------------------------------------------------------------------------------------------
# 6. CREATE NEW CONTROLLED ADAPTER
