# ----------------------------------------------------------------------------------------------------------------------------

def priority_score_4d6ajb(
    name_value,
):

    text_4d6ajb = str(
        name_value
    ).lower()

    score_4d6ajb = 0


    high_priority_tokens_4d6ajb = (
        "4d6i",
        "historical",
        "final",
        "invocation",
        "schedule",
        "runner",
        "baseline",
        "factory",
        "state_builder",
    )


    for token_4d6ajb in high_priority_tokens_4d6ajb:

        if token_4d6ajb in text_4d6ajb:

            score_4d6ajb += 10


    return score_4d6ajb


