# ----------------------------------------------------------------------------------------------------------------------------
# 6. RESULT EXTRACTION HELPERS
# ----------------------------------------------------------------------------------------------------------------------------

def _result_value_4d6al(
    result,
    *names,
    default=None,
):

    if result is None:

        return default


    result_dict_4d6al = {}


    if hasattr(
        result,
        "__dict__",
    ):

        try:

            result_dict_4d6al = dict(
                vars(
                    result
                )
            )

        except Exception:

            result_dict_4d6al = {}


    for name_4d6al in names:

        if name_4d6al in result_dict_4d6al:

            return result_dict_4d6al[
                name_4d6al
            ]


        try:

            if hasattr(
                result,
                name_4d6al,
            ):

                return getattr(
                    result,
                    name_4d6al,
                )

        except Exception:

            pass


    return default


def _evaluated_outcome_4d6al(
    winner,
    evaluated_side,
):

    winner_text_4d6al = (
        ""
        if winner is None
        else str(
            winner
        ).strip().lower()
    )


    evaluated_side_text_4d6al = (
        str(
            evaluated_side
        )
        .strip()
        .lower()
    )


    if winner_text_4d6al in (
        "",
        "none",
        "draw",
        "tie",
    ):

        return (
            0,
            0,
            1,
            "Draw",
        )


    if winner_text_4d6al == evaluated_side_text_4d6al:

        return (
            1,
            0,
            0,
            "Win",
        )


    if winner_text_4d6al in (
        "player",
        "opponent",
    ):

        return (
            0,
            1,
            0,
            "Loss",
        )


    return (
        0,
        0,
        1,
        "Draw",
    )


