def card_name_4d6ap(
    value_4d6ap
):

    if isinstance(
        value_4d6ap,
        dict,
    ):

        return str(
            value_4d6ap.get(
                "name",
                "UNKNOWN",
            )
        )


    if isinstance(
        value_4d6ap,
        str,
    ):

        text_4d6ap = (
            value_4d6ap.strip()
        )


        # Try dictionary-like historical text.
        if (
            text_4d6ap.startswith("{")
            and
            text_4d6ap.endswith("}")
        ):

            try:

                parsed_4d6ap = ast.literal_eval(
                    text_4d6ap
                )

                if isinstance(
                    parsed_4d6ap,
                    dict,
                ):

                    return str(
                        parsed_4d6ap.get(
                            "name",
                            text_4d6ap,
                        )
                    )

            except Exception:

                pass


        return text_4d6ap


    return str(
        value_4d6ap
    )


