# ----------------------------------------------------------------------------------------------------------------------------
# 6. SOURCE-PROVEN STATE-BUILDER INVOCATION HELPER
# ----------------------------------------------------------------------------------------------------------------------------

def build_state_4d6aq(
    starting_side_4d6aq,
):

    # Try the known Notebook 48 historical state-builder contract first.
    attempts_4d6aq = [
        lambda: state_builder_4d6aq(
            player_card=copy.deepcopy(
                eevee_card_4d6aq
            ),
            opponent_card=copy.deepcopy(
                charmander_card_4d6aq
            ),
            starting_side=starting_side_4d6aq,
        ),

        lambda: state_builder_4d6aq(
            copy.deepcopy(
                eevee_card_4d6aq
            ),
            copy.deepcopy(
                charmander_card_4d6aq
            ),
            starting_side_4d6aq,
        ),

        lambda: state_builder_4d6aq(
            player_card=copy.deepcopy(
                eevee_card_4d6aq
            ),
            opponent_card=copy.deepcopy(
                charmander_card_4d6aq
            ),
        ),
    ]


    errors_4d6aq = []


    for attempt_4d6aq in (
        attempts_4d6aq
    ):

        try:

            state_4d6aq = (
                attempt_4d6aq()
            )

            if state_4d6aq is not None:

                return state_4d6aq

        except Exception as exc_4d6aq:

            errors_4d6aq.append(
                repr(
                    exc_4d6aq
                )
            )


    raise RuntimeError(
        "Unable to build Eevee vs Charmander BattleState.\n"
        f"Errors: {errors_4d6aq}"
    )


# ----------------------------------------------------------------------------------------------------------------------------
# 7. DECISION INVOCATION HELPER
# ----------------------------------------------------------------------------------------------------------------------------

def choose_move_4d6aq(
    adapter_4d6aq,
    state_4d6aq,
):

    try:

        return adapter_4d6aq.choose_move(
            state=state_4d6aq,
            depth=6,
        )

    except TypeError:

        try:

            return adapter_4d6aq.choose_move(
                battle_state=state_4d6aq,
                depth=6,
            )

        except TypeError:

            return adapter_4d6aq.choose_move(
                state_4d6aq
            )


# ----------------------------------------------------------------------------------------------------------------------------
# 8. DECISION FIELD HELPER
# ----------------------------------------------------------------------------------------------------------------------------

def decision_value_4d6aq(
    decision_4d6aq,
    name_4d6aq,
    default=None,
):

    try:

        return getattr(
            decision_4d6aq,
            name_4d6aq,
            default,
        )

    except Exception:

        return default


def move_name_4d6aq(
    move_4d6aq,
):

    if move_4d6aq is None:

        return None


    if isinstance(
        move_4d6aq,
        dict,
    ):

        for key_4d6aq in [
            "Move Name",
            "move_name",
            "name",
        ]:

            if key_4d6aq in move_4d6aq:

                return str(
                    move_4d6aq[
                        key_4d6aq
                    ]
                )


    for attr_4d6aq in [
        "name",
        "move_name",
    ]:

        if hasattr(
            move_4d6aq,
            attr_4d6aq,
        ):

            try:

                return str(
                    getattr(
                        move_4d6aq,
                        attr_4d6aq,
                    )
                )

            except Exception:

                pass


    return str(
        move_4d6aq
    )


